/* @lc app=leetcode id=2836 lang=kotlin */ class Solution { fun getMaxFunctionValue(receiver: List<Int>, k: Long): Long = receiver.size.let { n -> Array(35) { IntArray(n) }.let { nxt -> Array(35) { LongArray(n) }.let { sum -> (0 until n).forEach { j -> nxt[0][j] = receiver[j].also { sum[0][j] = receiver[j].toLong() } }.let { (1 until 35).forEach { i -> (0 until n).forEach { j -> nxt[i][j] = nxt[i - 1][nxt[i - 1][j]].also { sum[i][j] = sum[i - 1][j] + sum[i - 1][nxt[i - 1][j]] } } } }.let { (0 until n).maxOf { i -> longArrayOf(i.toLong(), i.toLong()).let { state -> (0 until 35).forEach { b -> if ((k shr b) and 1L == 1L) state.also { it[1] = it[1] + sum[b][it[0].toInt()] }.also { it[0] = nxt[b][it[0].toInt()].toLong() } }.run { state[1] } } } } } } } }